@Composable
fun HomeVolume(
    onOpenCompanion: () -> Unit,
) {
    var selection by remember { mutableStateOf(MuseumSelectionStore.current) }
    var museumScene by remember { mutableStateOf<MuseumScene?>(null) }
    val navigator = LocalSpatialNavigator.current

    fun updateSelection(next: MuseumSelection) {
        selection = next
        MuseumSelectionStore.update(next)
    }

    Column(modifier = Modifier.padding(16.dp)) {
        Text("Luna Museum")
        Spacer(modifier = Modifier.height(8.dp))
        Text("Select an exhibit to inspect it in 3D.")
        Spacer(modifier = Modifier.height(12.dp))

        SpatialView(
            modifier = Modifier
                .fillMaxWidth()
                .size(260.dp)
                .clip(RoundedCornerShape(18.dp)),
            update = { _, _ ->
                museumScene?.apply(selection)
            },
            initial = { content, _ ->
                val scene = createMuseumScene()
                museumScene = scene
                content.addEntity(scene.root)
                scene.apply(selection)
            },
        )

        Spacer(modifier = Modifier.height(12.dp))
        Text(selection.selected.title)
        Text(selection.selected.description)
        Spacer(modifier = Modifier.height(10.dp))

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            Button(onClick = {
                updateSelection(selection.select(MuseumObject.HANDLED_CUP))
            }) {
                Text("Cup")
            }
            Button(onClick = {
                updateSelection(selection.select(MuseumObject.ROBOT_VACUUM))
            }) {
                Text("Vacuum")
            }
            Button(onClick = {
                updateSelection(selection.select(MuseumObject.SMART_SPEAKER))
            }) {
                Text("Speaker")
            }
        }

        Spacer(modifier = Modifier.height(8.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Button(onClick = { updateSelection(selection.turn()) }) {
                Text("Turn")
            }
            Button(onClick = { updateSelection(selection.reset()) }) {
                Text("Reset")
            }
            Button(onClick = onOpenCompanion) {
                Text("Open companion")
            }
        }
    }
}

private class MuseumScene(
    val root: Entity,
    private val objects: Map<MuseumObject, Entity>,
) {
    fun apply(selection: MuseumSelection) {
        objects.forEach { (museumObject, entity) ->
            entity.enabled = museumObject == selection.selected
            if (museumObject == selection.selected) {
                val transform = entity.components[TransformComponent::class.java] ?: return@forEach
                transform.eulerAngles = EulerAngles(
                    0f,
                    selection.turnQuarterTurns * 90f,
                    0f,
                )
            }
        }
    }
}

private fun createMuseumScene(): MuseumScene {
    val root = Entity()
    val cup = createCup()
    val vacuum = createRobotVacuum()
    val speaker = createSmartSpeaker()

    root.addChild(cup)
    root.addChild(vacuum)
    root.addChild(speaker)

    return MuseumScene(
        root = root,
        objects = mapOf(
            MuseumObject.HANDLED_CUP to cup,
            MuseumObject.ROBOT_VACUUM to vacuum,
            MuseumObject.SMART_SPEAKER to speaker,
        ),
    )
}

private fun createCup(): Entity {
    val cup = Entity()
    cup.components[TransformComponent::class.java] = TransformComponent(
        position = Vector3(0f, 0f, 0f),
        rotation = EulerAngles(0f, 0f, 0f),
        scale = Vector3(0.55f, 0.55f, 0.55f),
    )
    cup.addChild(model(MeshResource.createCylinder(0.7f, 0.42f), Color4(0.9f, 0.35f, 0.25f, 1f)))
    cup.addChild(model(MeshResource.createCylinder(0.08f, 0.5f), Color4(1f, 0.75f, 0.35f, 1f), Vector3(0f, 0.38f, 0f)))
    cup.addChild(model(MeshResource.createBox(Vector3(0.12f, 0.42f, 0.12f), 0.04f), Color4(1f, 0.7f, 0.25f, 1f), Vector3(0.42f, 0f, 0f)))
    cup.addChild(model(MeshResource.createBox(Vector3(0.12f, 0.12f, 0.45f), 0.04f), Color4(1f, 0.7f, 0.25f, 1f), Vector3(0.42f, 0.2f, 0f)))
    cup.addChild(model(MeshResource.createBox(Vector3(0.12f, 0.12f, 0.45f), 0.04f), Color4(1f, 0.7f, 0.25f, 1f), Vector3(0.42f, -0.2f, 0f)))
    return cup
}

private fun createRobotVacuum(): Entity {
    val vacuum = Entity()
    vacuum.components[TransformComponent::class.java] = TransformComponent(
        position = Vector3(0f, 0f, 0f),
        rotation = EulerAngles(0f, 0f, 0f),
        scale = Vector3(0.8f, 0.8f, 0.8f),
    )
    vacuum.addChild(model(MeshResource.createCylinder(0.25f, 0.55f), Color4(0.18f, 0.25f, 0.32f, 1f)))
    vacuum.addChild(model(MeshResource.createCylinder(0.08f, 0.3f), Color4(0.25f, 0.75f, 0.8f, 1f), Vector3(0f, 0.28f, 0f)))
    vacuum.addChild(model(MeshResource.createSphere(0.1f), Color4(0.9f, 0.9f, 0.95f, 1f), Vector3(0f, 0.36f, 0f)))
    return vacuum
}

private fun createSmartSpeaker(): Entity {
    val speaker = Entity()
    speaker.components[TransformComponent::class.java] = TransformComponent(
        position = Vector3(0f, 0f, 0f),
        rotation = EulerAngles(0f, 0f, 0f),
        scale = Vector3(0.65f, 0.65f, 0.65f),
    )
    speaker.addChild(model(MeshResource.createBox(Vector3(0.7f, 0.9f, 0.7f), 0.18f), Color4(0.35f, 0.28f, 0.55f, 1f)))
    speaker.addChild(model(MeshResource.createCylinder(0.08f, 0.2f), Color4(0.35f, 0.9f, 0.75f, 1f), Vector3(0f, 0.5f, 0f)))
    return speaker
}

private fun model(
    mesh: MeshResource,
    color: Color4,
    position: Vector3 = Vector3(0f, 0f, 0f),
): ModelEntity {
    val material = UnlitMaterial.create()
    material.setBaseColor(color)
    return ModelEntity(mesh, material).also {
        it.components[TransformComponent::class.java] = TransformComponent(
            position = position,
            rotation = EulerAngles(0f, 0f, 0f),
            scale = Vector3(1f, 1f, 1f),
        )
    }
}

package dev.local.lunamuseum.reproduction.content

import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import com.pico.spatial.ui.design.Button
import com.pico.spatial.ui.design.Text
import com.pico.spatial.ui.foundation.dsl.SpatialNavigator
import com.pico.spatial.ui.platform.containers.LocalSpatialNavigator

object CompanionWindow {
    const val ID = "luna-museum-companion"

    fun open(navigator: SpatialNavigator) {
        navigator.openWindowContainer(ID, tag = TAG)
    }

    @Composable
    fun Content() {
        val navigator = LocalSpatialNavigator.current
        var selection by remember { mutableStateOf(MuseumSelectionStore.current) }

        Text("Companion exhibit")
        Text(selection.selected.title)
        Text(selection.selected.description)
        Text("Quarter turns: ${selection.turnQuarterTurns}")

        Button(onClick = {
            val next = selection.turn()
            selection = next
            MuseumSelectionStore.update(next)
        }) {
            Text("Turn")
        }
        Button(onClick = {
            selection = MuseumSelectionStore.current
        }) {
            Text("Refresh")
        }
        Button(onClick = {
            navigator.closeWindowContainer()
        }) {
            Text("Close")
        }
    }

    private const val TAG = "museum-companion"
}

package dev.local.lunamuseum.reproduction.content

object MuseumSelectionStore {
    private var selection: MuseumSelection = MuseumSelection()

    val current: MuseumSelection
        @Synchronized get() = selection

    @Synchronized
    fun update(next: MuseumSelection) {
        selection = next
    }

    @Synchronized
    fun reset() {
        selection = MuseumSelection()
    }
}

package dev.local.lunamuseum.reproduction.content

import org.junit.Assert.assertEquals
import org.junit.Before
import org.junit.Test

class MuseumSelectionStoreTest {
    @Before
    fun resetStore() {
        MuseumSelectionStore.reset()
    }

    @Test
    fun companionReadsTheLatestHomeSelection() {
        val selection = MuseumSelection()
            .select(MuseumObject.ROBOT_VACUUM)
            .turn()

        MuseumSelectionStore.update(selection)

        assertEquals(selection, MuseumSelectionStore.current)
    }

    @Test
    fun storeResetRestoresTheDefaultSelection() {
        MuseumSelectionStore.update(
            MuseumSelection(
                selected = MuseumObject.SMART_SPEAKER,
                turnQuarterTurns = 2,
            ),
        )

        MuseumSelectionStore.reset()

        assertEquals(MuseumSelection(), MuseumSelectionStore.current)
    }
}
